// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  interpolateColors,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

// Load Google Font at module level
const { fontFamily: montserratFamily } = loadMontserrat();



export type GameShowQuizProps = Record<string, any>;

const GameShowQuiz: React.FC<GameShowQuizProps> = ({
  backgroundColor = "#03091e",
  transparentBackground = false,
  durationInSeconds = 7,
  title = "Malloy Studio",
  optionA = "Upgraded a 1.7m condo to 3.5m portfolio",
  optionB = "Paper gains of $300,000 in 2 years",
  optionC = "Now holds 2 private properties",
  optionD = "All of the above",
  correctOption = "D",
  headerFontSize = 80,
  optionsFontSize = 32,
  highlightColor = "#ffd700",
  borderColor = "#0f5cf2",
  textColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Prevent parser safety issues with background opacity fallback
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Header Title intro spring
  const headerProgress = spring({
    frame: frame - 5,
    fps,
    config: { damping: 12 },
  });
  const headerY = interpolate(headerProgress, [0, 1], [-40, 0]);
  const headerOpacity = interpolate(headerProgress, [0, 1], [0, 1]);

  // Divider expansion progress
  const dividerProgress = spring({
    frame: frame - 10,
    fps,
    config: { damping: 15 },
  });
  const dividerWidth = interpolate(dividerProgress, [0, 1], [0, 74]); // percentage

  // Reveal transition for the correct answer
  // Occurs from frame 105 to 115 (around 3.5 seconds)
  const revealStartFrame = 105;
  const revealProgress = interpolate(
    frame,
    [revealStartFrame, revealStartFrame + 10],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Generate deterministic particles for correct answer burst
  const particles = Array.from({ length: 24 }).map((_, idx) => {
    const angle = random(`p-angle-${idx}`) * 2 * Math.PI;
    const speed = 3 + random(`p-speed-${idx}`) * 7;
    const maxDistance = 120 + random(`p-dist-${idx}`) * 240;
    const size = 8 + random(`p-size-${idx}`) * 14;
    const delay = Math.floor(random(`p-delay-${idx}`) * 12);
    const emitterOffsetPct = 0.15 + random(`p-emit-${idx}`) * 0.7; // emit uniformly along the card length
    return { angle, speed, maxDistance, size, delay, emitterOffsetPct };
  });

  // Base card positioning configurations
  const cardWidth = width * 0.86;
  const cardHeight = height * 0.082;
  const gap = height * 0.016;

  // Render horizontal pointy hexagon shape for container
  const renderCapsulePath = (w: number, h: number) => {
    const inset = h * 0.25;
    return `
      M ${inset} 0
      L ${w - inset} 0
      L ${w} ${h / 2}
      L ${w - inset} ${h}
      L ${inset} ${h}
      L 0 ${h / 2}
      Z
    `;
  };

  // Render vertical pointy regular-like hexagon for badge
  const renderBadgePath = (h: number) => {
    const w = h * 1.15;
    return `
      M ${h * 0.288} 0
      L ${h * 0.862} 0
      L ${w} ${h / 2}
      L ${h * 0.862} ${h}
      L ${h * 0.288} ${h}
      L 0 ${h / 2}
      Z
    `;
  };

  const optionsData = [
    { letter: "A" as const, text: optionA },
    { letter: "B" as const, text: optionB },
    { letter: "C" as const, text: optionC },
    { letter: "D" as const, text: optionD },
  ];

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: montserratFamily,
        overflow: "hidden",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
      }}
    >
      {/* 1. Futuristic Digital Grid Pattern Overlay */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          backgroundImage: "radial-gradient(rgba(22, 94, 230, 0.12) 1.5px, transparent 1.5px)",
          backgroundSize: "32px 32px",
          opacity: 0.85,
          pointerEvents: "none",
        }}
      />

      {/* 2. Top-Left / Top-Right Spotlight Atmosphere */}
      <div
        style={{
          position: "absolute",
          top: -height * 0.05,
          left: -width * 0.1,
          width: width * 0.6,
          height: width * 0.6,
          borderRadius: "50%",
          background: "radial-gradient(circle, rgba(22, 94, 230, 0.45) 0%, rgba(22, 94, 230, 0) 70%)",
          filter: "blur(20px)",
          pointerEvents: "none",
        }}
      />
      <div
        style={{
          position: "absolute",
          top: -height * 0.05,
          right: -width * 0.1,
          width: width * 0.6,
          height: width * 0.6,
          borderRadius: "50%",
          background: "radial-gradient(circle, rgba(22, 94, 230, 0.45) 0%, rgba(22, 94, 230, 0) 70%)",
          filter: "blur(20px)",
          pointerEvents: "none",
        }}
      />

      {/* 3. Concentric Digital Circles at Bottom (Stage Floor Effect) */}
      <div
        style={{
          position: "absolute",
          bottom: -height * 0.12,
          left: "50%",
          transform: "translateX(-50%) rotateX(75deg)",
          transformOrigin: "bottom center",
          width: width * 1.8,
          height: height * 0.45,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          pointerEvents: "none",
          opacity: 0.65,
        }}
      >
        <div style={{ position: "absolute", width: "100%", height: "100%", borderRadius: "50%", border: "2px solid rgba(22, 94, 230, 0.35)", boxShadow: "0 0 25px rgba(22, 94, 230, 0.2)" }} />
        <div style={{ position: "absolute", width: "80%", height: "80%", borderRadius: "50%", border: "1.5px solid rgba(22, 94, 230, 0.25)" }} />
        <div style={{ position: "absolute", width: "60%", height: "60%", borderRadius: "50%", border: "1px solid rgba(22, 94, 230, 0.18)" }} />
        <div style={{ position: "absolute", width: "40%", height: "40%", borderRadius: "50%", border: "1px solid rgba(22, 94, 230, 0.12)" }} />
      </div>

      {/* 4. Quiz Header Segment */}
      <div
        style={{
          marginTop: height * 0.1,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          width: "100%",
          transform: `translateY(${headerY}px)`,
          opacity: headerOpacity,
          zIndex: 5,
        }}
      >
        <h1
          style={{
            fontSize: headerFontSize,
            fontWeight: 800,
            color: "#ffffff",
            margin: 0,
            padding: "0 20px",
            textAlign: "center",
            letterSpacing: "1px",
            textShadow: "0 4px 12px rgba(0, 0, 0, 0.5)",
          }}
        >
          {title}
        </h1>

        {/* Separator Divider with Lens Flare */}
        <div
          style={{
            position: "relative",
            width: `${dividerWidth}%`,
            height: "2px",
            background: "linear-gradient(90deg, transparent, #165ee6 40%, #165ee6 60%, transparent)",
            marginTop: 20,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
          }}
        >
          {/* Central Glow Core */}
          <div
            style={{
              position: "absolute",
              width: 14,
              height: 14,
              borderRadius: "50%",
              backgroundColor: "#ffffff",
              boxShadow: "0 0 16px 5px #165ee6, 0 0 30px 10px #165ee6",
            }}
          />
          {/* Wide Stretched Lens Flare Beam */}
          <div
            style={{
              position: "absolute",
              width: 160,
              height: 4,
              borderRadius: "50%",
              backgroundColor: "#ffffff",
              opacity: 0.85,
              boxShadow: "0 0 12px 3px #165ee6",
              transform: "scaleX(1.8)",
            }}
          />
        </div>
      </div>

      {/* 5. Stack of Staggered Hexagon Option Cards */}
      <div
        style={{
          marginTop: height * 0.06,
          display: "flex",
          flexDirection: "column",
          gap: gap,
          width: "100%",
          alignItems: "center",
          zIndex: 10,
        }}
      >
        {optionsData.map((item, index) => {
          const isThisCorrect = correctOption === item.letter;

          // Sequential entrance frame offset
          const entranceStartFrame = 20 + index * 20;
          const entrySpring = spring({
            frame: frame - entranceStartFrame,
            fps,
            config: { damping: 13, mass: 0.9 },
          });

          const entryProgress = frame >= entranceStartFrame ? entrySpring : 0;

          // Animations on load
          const cardX = interpolate(entryProgress, [0, 1], [-width * 0.6, 0]);
          const cardOpacity = interpolate(entryProgress, [0, 1], [0, 1]);
          const cardScale = interpolate(entryProgress, [0, 1], [0.85, 1]);

          // Transition styling for Correct Answer Reveal
          const activeProgress = isThisCorrect ? revealProgress : 0;

          // Interactive Color Interpolations (Blue to Gold)
          const fillBase = "rgba(2, 10, 30, 0.72)";
          const fillTarget = "rgba(212, 175, 55, 0.16)";
          const cardFill = interpolateColors(activeProgress, [0, 1], [fillBase, fillTarget]);

          const strokeBase = borderColor;
          const strokeTarget = highlightColor;
          const cardBorder = interpolateColors(activeProgress, [0, 1], [strokeBase, strokeTarget]);

          const textBase = textColor;
          const textTarget = highlightColor;
          const cardTextColor = interpolateColors(activeProgress, [0, 1], [textBase, textTarget]);

          const letterTextBase = "#ffffff";
          const letterTextTarget = "#03091e";
          const badgeLetterColor = interpolateColors(activeProgress, [0, 1], [letterTextBase, letterTextTarget]);

          // Pulse & Glow Animation triggers once revealed
          const pulseScale = isThisCorrect && frame >= revealStartFrame + 10
            ? 1 + 0.016 * Math.sin((frame - (revealStartFrame + 10)) * 0.25)
            : 1;

          const glowIntensity = isThisCorrect && frame >= revealStartFrame
            ? 15 + 15 * Math.sin((frame - revealStartFrame) * 0.25)
            : 8;

          const shadowColor = isThisCorrect
            ? `rgba(212, 175, 55, ${interpolate(activeProgress, [0, 1], [0.3, 0.8])})`
            : "rgba(15, 92, 242, 0.3)";

          const filterStyle = `drop-shadow(0 0 ${glowIntensity}px ${shadowColor})`;

          // Diagonal Sheen Sweep effect during correct reveal
          const sweepFrameStart = revealStartFrame + 5;
          const sweepProgress = interpolate(
            frame,
            [sweepFrameStart, sweepFrameStart + 25],
            [-0.8, 1.8],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          return (
            <div
              key={item.letter}
              style={{
                position: "relative",
                width: cardWidth,
                height: cardHeight,
                opacity: cardOpacity,
                transform: `translateX(${cardX}px) scale(${cardScale * pulseScale})`,
                filter: filterStyle,
                display: "flex",
                alignItems: "center",
                transition: "none",
              }}
            >
              {/* Main Hexagonal Capsule Outer Border + Backdrop */}
              <svg
                width={cardWidth}
                height={cardHeight}
                viewBox={`0 0 ${cardWidth} ${cardHeight}`}
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  overflow: "visible",
                }}
              >
                <path
                  d={renderCapsulePath(cardWidth, cardHeight)}
                  fill={cardFill}
                  stroke={cardBorder}
                  strokeWidth={3}
                  strokeLinejoin="round"
                />
              </svg>

              {/* Diagonal Light Sweep Over Correct Card */}
              {isThisCorrect && sweepProgress > -0.8 && sweepProgress < 1.8 && (
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    overflow: "hidden",
                    pointerEvents: "none",
                    clipPath: `path("${renderCapsulePath(cardWidth, cardHeight).replace(/\s+/g, " ").trim()}")`,
                  }}
                >
                  <div
                    style={{
                      position: "absolute",
                      top: 0,
                      left: `${sweepProgress * 100}%`,
                      width: "35%",
                      height: "100%",
                      background: "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.45), transparent)",
                      transform: "skewX(-28deg)",
                      mixBlendMode: "overlay",
                    }}
                  />
                </div>
              )}

              {/* Left Pointy Hexagon Badge containing the Option Letter */}
              <div
                style={{
                  position: "absolute",
                  left: 0,
                  top: 0,
                  width: cardHeight * 1.15,
                  height: cardHeight,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <svg
                  width={cardHeight * 1.15}
                  height={cardHeight}
                  viewBox={`0 0 ${cardHeight * 1.15} ${cardHeight}`}
                  style={{
                    position: "absolute",
                    top: 0,
                    left: 0,
                  }}
                >
                  <defs>
                    <linearGradient id="blueBadgeGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                      <stop offset="0%" stopColor="#0d3fb0" />
                      <stop offset="100%" stopColor="#165ee6" />
                    </linearGradient>
                    <linearGradient id="goldBadgeGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                      <stop offset="0%" stopColor="#ffd700" />
                      <stop offset="100%" stopColor="#b8860b" />
                    </linearGradient>
                  </defs>

                  {/* Base Blue Hexagon Badge */}
                  <path
                    d={renderBadgePath(cardHeight)}
                    fill="url(#blueBadgeGrad)"
                    stroke={borderColor}
                    strokeWidth={2.5}
                    style={{
                      opacity: 1 - activeProgress,
                    }}
                  />

                  {/* Correct Gold Hexagon Badge Overlay */}
                  <path
                    d={renderBadgePath(cardHeight)}
                    fill="url(#goldBadgeGrad)"
                    stroke={highlightColor}
                    strokeWidth={2.5}
                    style={{
                      opacity: activeProgress,
                    }}
                  />
                </svg>

                {/* Option Letter Label inside Badge */}
                <span
                  style={{
                    position: "relative",
                    fontSize: cardHeight * 0.42,
                    fontWeight: 900,
                    color: badgeLetterColor,
                    zIndex: 2,
                    textShadow: activeProgress > 0.5 ? "none" : "0 2px 4px rgba(0,0,0,0.3)",
                  }}
                >
                  {item.letter}
                </span>
              </div>

              {/* Option Text Label */}
              <div
                style={{
                  boxSizing: "border-box",
                  width: "100%",
                  height: "100%",
                  paddingLeft: cardHeight * 1.34,
                  paddingRight: cardHeight * 0.35,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "flex-start",
                  zIndex: 2,
                }}
              >
                <p
                  style={{
                    color: cardTextColor,
                    fontSize: optionsFontSize,
                    fontWeight: isThisCorrect && frame >= revealStartFrame ? 800 : 600,
                    margin: 0,
                    lineHeight: 1.25,
                    textAlign: "left",
                    wordBreak: "break-word",
                  }}
                >
                  {item.text}
                </p>
              </div>

              {/* Spectacular Golden Sparkle Particle Burst */}
              {isThisCorrect && frame >= revealStartFrame && (
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    pointerEvents: "none",
                    overflow: "visible",
                  }}
                >
                  {particles.map((p, idx) => {
                    const relativeFrame = frame - revealStartFrame - p.delay;
                    if (relativeFrame <= 0 || relativeFrame > 35) return null;

                    // Compute current radial distance from parent bounds
                    const distance = interpolate(
                      relativeFrame,
                      [0, 32],
                      [0, p.maxDistance],
                      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
                    );

                    // Compute dynamic coordinate starting from a point along the card
                    const emitterX = cardWidth * p.emitterOffsetPct;
                    const emitterY = cardHeight / 2;
                    const x = Math.cos(p.angle) * distance + emitterX;
                    const y = Math.sin(p.angle) * distance + emitterY;

                    const pOpacity = interpolate(relativeFrame, [20, 32], [1, 0], {
                      extrapolateLeft: "clamp",
                      extrapolateRight: "clamp",
                    });

                    const pRot = interpolate(relativeFrame, [0, 32], [0, 270]);

                    return (
                      <svg
                        key={idx}
                        style={{
                          position: "absolute",
                          left: x,
                          top: y,
                          width: p.size,
                          height: p.size,
                          opacity: pOpacity,
                          transform: `translate(-50%, -50%) rotate(${pRot}deg)`,
                          pointerEvents: "none",
                          transition: "none",
                        }}
                        viewBox="0 0 24 24"
                      >
                        {/* 4-pointed sparkle vector shape */}
                        <path
                          d="M12 0 L15.5 8.5 L24 12 L15.5 15.5 L12 24 L8.5 15.5 L0 12 L8.5 8.5 Z"
                          fill="#ffd700"
                        />
                      </svg>
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default GameShowQuiz;